'use strict';
// Upstairs study notes: questions for a class and the sources behind each step (built from resources/sources-v17).
window.BD_ACCOUNTS_STUDY = {"steps": {"Creation": {"ask": ["Genesis 1 was written for people who knew stories like Enuma Elish. Which details in Genesis 1 read like a deliberate answer to those stories?", "If every person bears God’s image (Genesis 1:27), what follows for how you treat someone you disagree with?"], "sources": ["enuma-elish", "genealogies"]}, "Fall": {"ask": ["The serpent’s first move is a question about what God said (Genesis 3:1). Where do you hear the same question today?", "Adam blames Eve and Eve blames the serpent. What does God do next, in Genesis 3:15 and 3:21?"], "sources": ["protevangelium", "atrahasis"]}, "Promise": {"ask": ["Abraham left a wealthy city for tents. What did he have to trust that he could not see (Hebrews 11:8–10)?", "God promised a blessing for all the families of the earth (Genesis 12:3). Where does the New Testament say that promise is being kept (Galatians 3:8)?"], "sources": ["ur-woolley", "mari-archives", "beni-hasan", "slave-price"]}, "Exodus": {"ask": ["Christians hold two dates for the Exodus. Which arguments for each seem strongest, and does the choice affect whether it happened?", "Why was Israel told to retell the Exodus every year (Exodus 12:26–27)? What do you retell, and why?"], "sources": ["exodus-dates", "brooklyn-papyrus", "brick-quotas", "egypt-silence", "merneptah-stele"]}, "Law": {"ask": ["God says who he is and what he has done before he gives a single command (Exodus 20:2). Why does that order matter?", "Compare “eye for eye” in Hammurabi’s laws and in Exodus 21. What differences do you notice, and what do they say about God?"], "sources": ["treaty-covenant", "hammurabi"]}, "Land": {"ask": ["Jericho’s date is debated among archaeologists. How should a Christian talk about a question where the evidence is still being argued?", "Joshua ends with a choice, not a victory parade (Joshua 24:15). Why?"], "sources": ["amarna-letters", "jericho-dates", "hazor-ai", "hill-villages"]}, "King": {"ask": ["Before 1993 some scholars called David a legend. What changed, and what is still debated?", "God promised David a kingdom that would last for ever (2 Samuel 7:16). How does Luke 1:32–33 claim that promise for Jesus?"], "sources": ["tel-dan-stele", "qeiyafa-fortress", "david-jerusalem", "solomon-gates", "ain-dara"]}, "Prophets": {"ask": ["Assyria’s records praise its kings. The Bible records its own kings’ failures. What does that difference tell a historian?", "Amos was a herdsman sent to a rich king’s shrine (Amos 7:14–15). What gave the prophets their courage?"], "sources": ["black-obelisk", "kurkh-monolith", "samaria-ivories", "sargon-samaria", "sennacherib-prism"]}, "Exile": {"ask": ["Jeremiah told the exiles to seek the welfare of Babylon (Jeremiah 29:7). What would that look like where you live?", "Other deported peoples disappeared. Why do you think Judah did not?"], "sources": ["babylonian-chronicle", "lachish-letters", "jehoiachin-rations", "al-yahudu", "nabonidus-belshazzar"]}, "Return": {"ask": ["The Cyrus Cylinder shows a policy but does not mention Judah. How would you state carefully what it shows?", "The old men wept and the young shouted (Ezra 3:12–13). When have you felt both about something God was rebuilding?"], "sources": ["cyrus-cylinder", "isaiah-cyrus", "elephantine"]}, "Jesus": {"ask": ["Luke ties Jesus’ birth and ministry to named rulers (Luke 2:1–2; 3:1–2). Why would a writer invite that kind of checking?", "Jesus grew up in a village of a few hundred people. What does that say about how God works?"], "sources": ["roman-world", "birth-census", "herod-the-great", "nazareth"]}, "Cross": {"ask": ["Roman writers avoided even describing crucifixion. Why would the first Christians put a crucified man at the center of their message (1 Corinthians 1:23)?", "Tacitus despised Christians and still records that Pilate executed Christ. Why does a hostile witness carry weight?"], "sources": ["crucifixion-date", "crucifixion-rome", "pilate-stone", "caiaphas-ossuary", "yehohanan", "nero-tacitus"]}, "Risen": {"ask": ["Most historians accept these facts: Jesus died by crucifixion, he was buried, his tomb was reported empty, his followers believed they saw him alive, and James and Paul changed sides. Which explanation accounts for all of them?", "Paul says that if Christ is not raised, faith is futile (1 Corinthians 15:14–17). Why would he stake everything on a claim people could check?"], "sources": ["resurrection-creed", "empty-tomb-women", "holy-sepulchre"]}, "Spirit": {"ask": ["At Pentecost people from many nations heard God’s works in their own languages. How does that answer Babel (Genesis 11:1–9)?", "Peter denied Jesus to a servant girl, and seven weeks later preached to thousands. What explains the change?"], "sources": ["pentecost", "luke-accuracy", "antioch"]}, "Church": {"ask": ["About AD 112 Pliny reports that Christians sang “to Christ as to a god.” What does that tell us about belief in Jesus’ divinity before any council?", "The early church grew by caring for the sick and the unwanted. What would that look like in your school or town?"], "sources": ["peter-paul-rome", "pliny-trajan", "megiddo-mosaic", "dura-europos", "church-growth"]}, "New Creation": {"ask": ["Is the Christian hope escape from the world, or the world made new? Read Romans 8:19–23 and Revelation 21:1–5.", "How should a sure hope of resurrection change the way you face fear, grief or ambition today?"], "sources": ["new-creation", "laodicea-water", "domitian"]}}, "sources": {"ain-dara": {"id": "ain-dara", "label": "The ‘Ain Dara temple · the closest parallel to Solomon’s plan", "citation": "John Monson, “The New ‘Ain Dara Temple: Closest Solomonic Parallel,” Biblical Archaeology Review 26:3 (2000); Ali Abu Assaf’s excavation report, Der Tempel von ‘Ain Dara (1990).", "trail": "Excavation in northern Syria (1980s) → Abu Assaf 1990 → Monson 2000.", "note": "A temple of the 10th–8th centuries BC with a porch, a main hall and an inner room, side chambers and two pillars at the entrance, the same three-part plan as 1 Kings 6. The building was badly damaged in fighting in 2018.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "al-yahudu": {"id": "al-yahudu", "label": "Āl-Yāhūdu · “Judah-town” in Babylonia", "citation": "About 200 cuneiform tablets, 572–477 BC: Laurie E. Pearce and Cornelia Wunsch, Documents of Judean Exiles and West Semites in Babylonia in the Collection of David Sofer (CDL Press, 2014).", "trail": "Tablets that came through the antiquities market → Pearce and Wunsch 2014.", "note": "Contracts and receipts from a village of Judean exiles, with names built on Yahweh (such as Yahu-azar) across four generations. They show the exiles farming and trading, as Jeremiah 29:5–7 told them to. Because the tablets were not excavated, scholars use them with care over their exact origin.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "amarna-letters": {"id": "amarna-letters", "label": "The Amarna letters · Canaan’s kings write to Pharaoh", "citation": "About 380 clay tablets from Akhetaten (el-Amarna), Egypt, found in 1887, mid-14th century BC. William L. Moran, The Amarna Letters (Johns Hopkins, 1992). Letters EA 286–290 are from Abdi-Heba, king of Jerusalem.", "trail": "Tablets in Berlin, London and Cairo → J. A. Knudtzon’s numbering (1907–15) → Moran 1992.", "note": "The kings of Canaan’s small walled cities beg Pharaoh for archers and complain of the ‘Apiru (Habiru), raiders and outlaws. Some early-date scholars link the ‘Apiru with Joshua’s Hebrews. Most think the word names a social class rather than a people, though the Hebrews could have been counted among them.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "antioch": {"id": "antioch", "label": "Antioch and the name “Christians”", "citation": "Acts 11:19–26; Josephus, Jewish War 3.29 (Antioch the third city of the Roman world); Tacitus, Annals 15.44; Pliny, Letters 10.96.", "trail": "Josephus → Wayne A. Meeks and Robert L. Wilken, Jews and Christians in Antioch (Scholars Press, 1978).", "note": "Christianus is a Latin-style party name, like Herodiani; outsiders coined it. Within eighty years Roman officials use it as a legal label (Pliny, Tacitus).", "url": "", "consulted": "Compiled from the published record, November 2026."}, "atrahasis": {"id": "atrahasis", "label": "Atrahasis and Gilgamesh · the Mesopotamian flood stories", "citation": "Atra-hasis, Old Babylonian copy of the 17th century BC: W. G. Lambert and A. R. Millard, Atra-ḫasīs: The Babylonian Story of the Flood (Oxford, 1969). Gilgamesh, Tablet XI (the “Flood Tablet”), British Museum K.3375, read by George Smith in 1872: A. R. George, The Babylonian Gilgamesh Epic (Oxford, 2003).", "trail": "Clay tablets from Sippar and from Ashurbanipal’s library at Nineveh → Smith 1872; Lambert and Millard 1969 → George 2003.", "note": "In Atrahasis the gods try plague, drought and finally the flood because the noise of the growing human race keeps the god Enlil awake. Genesis shares the outline (a warned man, a boat, birds sent out, a sacrifice) and differs in its theology: one God, judging real wickedness, who then binds himself by covenant. Scholars debate whether the accounts remember a common event or Genesis answers the older stories; this book takes Genesis as the true account.", "url": "https://www.britishmuseum.org/collection/object/W_K-3375", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}, "babylonian-chronicle": {"id": "babylonian-chronicle", "label": "The Babylonian Chronicle · Jerusalem taken on 2 Adar 597 BC", "citation": "Chronicle 5 (the “Jerusalem Chronicle”), British Museum 21946. D. J. Wiseman, Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum (London, 1956); A. K. Grayson, Assyrian and Babylonian Chronicles (Locust Valley, 1975).", "trail": "The tablet → Wiseman 1956 → Grayson 1975 → Jean-Jacques Glassner, Mesopotamian Chronicles (Society of Biblical Literature, 2004).", "note": "It records Carchemish (605 BC, Jeremiah 46:2) and the capture of “the city of Judah” on 2 Adar of Nebuchadnezzar’s seventh year: 15/16 March 597 BC. The chronicles for 594–557 BC are missing, which is why 587 or 586 for Jerusalem’s fall is still argued.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-5-jerusalem-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, "beni-hasan": {"id": "beni-hasan", "label": "The Beni Hasan painting · visitors from Canaan, about 1890 BC", "citation": "Tomb of Khnumhotep II (tomb 3), Beni Hasan, Egypt. Percy E. Newberry, Beni Hasan, part I (London, 1893).", "trail": "The tomb painting → Newberry 1893 → Hoffmeier, Israel in Egypt (1997).", "note": "The caption counts 37 ‘Aamu (Asiatics) led by Abisha, “ruler of a foreign land” (heqa khasut, the phrase that later gives “Hyksos”). The bright woven cloth recalls Joseph’s robe, though the Hebrew of Genesis 37:3 is uncertain.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "birth-census": {"id": "birth-census", "label": "The birth of Jesus · Herod’s death and Luke’s census", "citation": "Josephus, Antiquities 17.167 and 17.191 (an eclipse before Herod’s death; his reign of 37 years from his appointment); Antiquities 18.1–2, 26 (Quirinius’ census, AD 6). British Library Papyrus 904 (AD 104): the prefect of Egypt orders people to return to their homes for a census. Harold W. Hoehner, Chronological Aspects of the Life of Christ (Zondervan, 1977), ch. 1.", "trail": "Josephus → the Egyptian census papyri → Hoehner; Andrew E. Steinmann, “When Did Herod the Great Reign?” Novum Testamentum 51 (2009): 1–29.", "note": "Most date Herod’s death to 4 BC; Steinmann and others argue for 1 BC. Dionysius Exiguus fixed the AD era in 525. Luke 2:2 is the hard question: Quirinius’ known census was AD 6. Proposed answers include reading prōtē as “before” the census under Quirinius, an earlier registration, or an earlier office held by Quirinius. None is proven; Luke elsewhere is careful with officials (Luke 3:1).", "url": "", "consulted": "Compiled from the published record, November 2026."}, "black-obelisk": {"id": "black-obelisk", "label": "The Black Obelisk · Jehu’s tribute, 841 BC", "citation": "Black Obelisk of Shalmaneser III, from Nimrud; British Museum, 1848,1104.1. Found by Austen Henry Layard in 1846; Nineveh and Its Remains (London, 1849). Edited in Grayson, Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (1996).", "trail": "The obelisk → Edward Hincks and Henry Rawlinson read the name in 1851 → Grayson 1996.", "note": "The caption calls him “Jehu, son of Omri.” Jehu was not Omri’s son; he ended that family (2 Kings 9–10). Assyrians called Israel the House of Omri for a century, so “son of Omri” means “of the land of Omri.” The kneeling figure may be Jehu himself or his envoy.", "url": "https://www.britishmuseum.org/collection/object/W_1848-1104-1", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}, "brick-quotas": {"id": "brick-quotas", "label": "Bricks and straw · the Egyptian records", "citation": "Tomb of Rekhmire (TT 100), Thebes, about 1450 BC: foreign workers making bricks; the Louvre Leather Roll (time of Ramesses II): brick quotas for work gangs; Papyrus Anastasi texts on brick-making. Collected in Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "Paintings and papyri → Kitchen 2003; Hoffmeier, Israel in Egypt (1997).", "note": "The records show quotas, foreign labor and straw in bricks, the conditions of Exodus 5. They do not name Israel; they show the writer of Exodus knew how Egypt worked.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "brooklyn-papyrus": {"id": "brooklyn-papyrus", "label": "Papyrus Brooklyn 35.1446 · Semitic servants in an Egyptian house", "citation": "Brooklyn Museum 35.1446, about 1740 BC. William C. Hayes, A Papyrus of the Late Middle Kingdom in the Brooklyn Museum (Brooklyn, 1955); W. F. Albright, “Northwest-Semitic Names in a List of Egyptian Slaves from the Eighteenth Century B.C.,” Journal of the American Oriental Society 74 (1954): 222–233.", "trail": "Papyrus → Hayes 1955 and Albright 1954 → Hoffmeier, Israel in Egypt (1997).", "note": "A list of about ninety-five servants in one household in Upper Egypt. Dozens are labeled “Asiatic” and carry Northwest Semitic names; Albright read one as Shiphrah, the name of a Hebrew midwife in Exodus 1:15. It shows Semitic people serving in Egyptian homes in the era of Joseph.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "caiaphas-ossuary": {"id": "caiaphas-ossuary", "label": "The Caiaphas ossuary", "citation": "Found in North Talpiot, Jerusalem, 1990; Israel Museum. Zvi Greenhut, “The ‘Caiaphas’ Tomb of North Talpiyot, Jerusalem,” ‘Atiqot 21 (1992): 63–71; Ronny Reich, “Caiaphas’ Name Inscribed on Bone Boxes,” Biblical Archaeology Review 18:5 (1992).", "trail": "The tomb → Greenhut and Reich 1992; an ossuary of “Miriam daughter of Yeshua son of Caiaphas” was published in 2011.", "note": "The inscription reads Yehosef bar Qayafa. A few scholars questioned the spelling and the identification; most accept that the ornate box belonged to the high priest’s family and probably to Caiaphas himself (Josephus, Antiquities 18.35).", "url": "", "consulted": "Compiled from the published record, November 2026."}, "church-growth": {"id": "church-growth", "label": "How the church grew", "citation": "Rodney Stark, The Rise of Christianity (Princeton, 1996); Dionysius of Alexandria on the plague, in Eusebius, Church History 7.22; Emperor Julian, Letter to Arsacius (about AD 362); Didache 2.2 and the Epistle to Diognetus 5.6 (Christians do not expose infants).", "trail": "Eusebius and Julian → Stark 1996.", "note": "Stark estimated about 40 percent growth per decade, reaching some six million Christians, about a tenth of the empire, by AD 300. These are estimates from models. Julian, who wanted paganism restored, complained that the Christians cared for their own poor and for pagans too.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "crucifixion-date": {"id": "crucifixion-date", "label": "The date of the crucifixion · AD 30 or 33", "citation": "Colin J. Humphreys and W. Graeme Waddington, “Dating the Crucifixion,” Nature 306 (1983): 743–746; Harold W. Hoehner, Chronological Aspects of the Life of Christ (1977); John P. Meier, A Marginal Jew, vol. 1 (Doubleday, 1991), ch. 11.", "trail": "Astronomical tables of the new moon → Humphreys and Waddington; Hoehner (AD 33) and Meier (AD 30).", "note": "Nisan 14 fell on a Friday in AD 30 (7 April) and AD 33 (3 April). The choice depends on when Jesus’ ministry began (Luke 3:1) and how John’s Passover timing relates to the other Gospels’ Passover meal.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "crucifixion-rome": {"id": "crucifixion-rome", "label": "Crucifixion in Roman writers", "citation": "Cicero, Against Verres 2.5.165 (“a most cruel and disgusting punishment”) and For Rabirius 16; Martin Hengel, Crucifixion in the Ancient World and the Folly of the Message of the Cross (Fortress, 1977).", "trail": "Cicero → Hengel 1977.", "note": "Hengel showed how seldom educated writers described crucifixion, and how shameful it was, which is why the Christian message about a crucified Lord sounded like “folly” (1 Corinthians 1:23). No one inventing a hero for that world would have chosen a cross.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "cyrus-cylinder": {"id": "cyrus-cylinder", "label": "The Cyrus Cylinder · the policy of return", "citation": "Clay cylinder, Babylon, after 539 BC; British Museum, 1880,0617.1941. Found by Hormuzd Rassam in 1879. Irving Finkel (ed.), The Cyrus Cylinder: The King of Persia’s Proclamation from Ancient Babylon (I. B. Tauris, 2013).", "trail": "The cylinder → Rawlinson’s first translation (1880) → Finkel 2013, with the fragments of a second copy identified in 2010.", "note": "Cyrus says he returned gods and peoples to their homes. It names places in Mesopotamia and western Iran, not Judah. It shows a policy; Ezra 1 and 6 record a decree for Jerusalem. Some historians think Cyrus’s generosity was more limited than his propaganda claims; Ezra’s decree fits the way Persian kings dealt with local temples.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}, "david-jerusalem": {"id": "david-jerusalem", "label": "David’s Jerusalem · the Large Stone Structure", "citation": "Eilat Mazar, “Did I Find King David’s Palace?” Biblical Archaeology Review 32:1 (2006); Israel Finkelstein, Ze’ev Herzog, Lily Singer-Avitz and David Ussishkin, “Has King David’s Palace in Jerusalem Been Found?” Tel Aviv 34 (2007): 142–164.", "trail": "City of David excavations (Kathleen Kenyon, Yigal Shiloh, Eilat Mazar) → the exchange above.", "note": "Mazar dated a massive building and the Stepped Stone Structure to David’s time; her critics date parts earlier or later. The size of David’s kingdom is debated; that a royal house of David existed is secured by the Tel Dan Stele.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "domitian": {"id": "domitian", "label": "Domitian, “lord and god”", "citation": "Suetonius, Domitian 13.2 (dominus et deus noster); Revelation 1:9; Irenaeus, Against Heresies 5.30.3 (Revelation seen near the end of Domitian’s reign).", "trail": "Suetonius and Irenaeus → Steven J. Friesen, Imperial Cults and the Apocalypse of John (Oxford, 2001).", "note": "Historians differ on how widespread persecution under Domitian was; the pressure in Revelation looks local and social as much as imperial. A minority dates Revelation before AD 70.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Suetonius/12Caesars/Domitian*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, "dura-europos": {"id": "dura-europos", "label": "Dura-Europos · the oldest house church", "citation": "Yale University and French Academy excavations, 1928–1937; Carl H. Kraeling, The Christian Building, Excavations at Dura-Europos, Final Report VIII.2 (Yale, 1967); Michael Peppard, The World’s Oldest Church (Yale, 2016). Paintings in the Yale University Art Gallery.", "trail": "Excavation → Kraeling 1967 → Peppard 2016.", "note": "A graffito dates the house’s remodeling to AD 232/233. Peppard argues the procession of women is the virgins of the parable rather than the women at the tomb; the scene is discussed both ways. The paintings include the Good Shepherd, the healing of the paralytic and Jesus and Peter on the water.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "egypt-silence": {"id": "egypt-silence", "label": "Why Egypt’s records are silent", "citation": "Kitchen, On the Reliability of the Old Testament (2003), ch. 6; Hoffmeier, Israel in Egypt (1997), ch. 5. On Kadesh: the Poem and the Bulletin of Ramesses II, carved at Karnak, Luxor, the Ramesseum and Abu Simbel; the Egyptian–Hittite peace treaty of about 1259 BC, copies at Karnak and Hattusa.", "trail": "Temple inscriptions and the Hattusa archives → Kitchen; Hoffmeier.", "note": "Almost no papyrus survives from the wet soil of the eastern Delta, where Israel lived, and the royal archives of the period are lost. Pharaohs did carve near-defeats, but as triumphs: Ramesses II portrayed the battle of Kadesh (1274 BC) as his victory, while Hittite records and the later treaty show a stalemate. Silence is expected; it is not evidence either way.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "elephantine": {"id": "elephantine", "label": "The Elephantine papyri · Nehemiah’s neighbors", "citation": "Aramaic papyri from a Jewish garrison at Elephantine, Egypt, 5th century BC. A. E. Cowley, Aramaic Papyri of the Fifth Century B.C. (Oxford, 1923), nos. 30–31; Bezalel Porten, The Elephantine Papyri in English (Brill, 1996).", "trail": "The papyri (Berlin, Brooklyn and Cairo) → Cowley 1923 → Porten 1996.", "note": "A letter of 407 BC to Bagohi, governor of Judah, mentions Johanan the high priest (Nehemiah 12:22) and the sons of Sanballat, governor of Samaria, Nehemiah’s opponent (Nehemiah 2:10). It sets Nehemiah’s people in a real Persian province.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "empty-tomb-women": {"id": "empty-tomb-women", "label": "The empty tomb and the women witnesses", "citation": "Mark 16:1–8; Matthew 28:11–15; Josephus, Antiquities 4.219 (women not admitted as legal witnesses); Richard Bauckham, Gospel Women (Eerdmans, 2002).", "trail": "The Gospels and Josephus → Bauckham 2002; William Lane Craig, “The Historicity of the Empty Tomb of Jesus,” New Testament Studies 31 (1985): 39–67.", "note": "Matthew reports the opponents’ answer, that the disciples stole the body, which assumes the tomb was empty. Naming women as the first witnesses was a weakness in that culture, which is why many historians count it as a mark of authenticity.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "enuma-elish": {"id": "enuma-elish", "label": "Enuma Elish and Genesis 1", "citation": "Enuma Elish, the Babylonian creation epic; copies from Ashurbanipal’s library at Nineveh and from Assur and Babylon. First published by George Smith, The Chaldean Account of Genesis (London, 1876). W. G. Lambert, Babylonian Creation Myths (Eisenbrauns, 2013).", "trail": "Tablets → Smith 1876 → Lambert 2013 → Gerhard F. Hasel, “The Polemic Nature of the Genesis Cosmology,” Evangelical Quarterly 46 (1974): 81–102.", "note": "Marduk makes the world from the split body of the goddess Tiamat after a war among the gods; humans are made from a slain god’s blood to do the gods’ work. Genesis 1 shares a word with it (tehom, “the deep,” related to Tiamat) and reads as a deliberate contrast: one God, no battle, the sun and moon as lamps rather than gods, people made in God’s image to rule and to rest. Lambert himself doubted that Genesis borrowed from the Babylonian story.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "exodus-dates": {"id": "exodus-dates", "label": "The date of the Exodus · 1446 BC or about 1260 BC", "citation": "Early date: 1 Kings 6:1; Judges 11:26; Bryant G. Wood, “The Rise and Fall of the 13th-Century Exodus-Conquest Theory,” Journal of the Evangelical Theological Society 48:3 (2005): 475–489; Eugene H. Merrill, Kingdom of Priests (2nd ed., Baker, 2008). Late date: Exodus 1:11; James K. Hoffmeier, Israel in Egypt (Oxford, 1997); Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "The biblical figures → the excavations at Qantir (Pi-Ramesse) by Edgar Pusch and Manfred Bietak → the two schools above.", "note": "Early-date scholars read the 480 years literally and note that “Rameses” can be a later name for the place, as Genesis 47:11 uses it for Joseph’s day. Late-date scholars read 480 as twelve generations of forty years and point to Pi-Ramesse, the Delta capital built by Ramesses II. A third view moves Egypt’s whole chronology; most Egyptologists reject it. Both main views take the Exodus as history.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "genealogies": {"id": "genealogies", "label": "Early dates and the genealogies of Genesis", "citation": "William Henry Green, “Primeval Chronology,” Bibliotheca Sacra 47 (1890): 285–303. For the conventional dates: writing at Uruk about 3200 BC; the Great Pyramid of Khufu about 2560 BC (Ian Shaw, ed., The Oxford History of Ancient Egypt, Oxford, 2000).", "trail": "Genesis 5 and 11 → Green 1890, a Princeton Old Testament scholar who held to inerrancy → present-day young-earth and old-earth discussion.", "note": "Green argued that biblical genealogies can skip generations, as Matthew 1:8 skips three kings between Joram and Uzziah, so they were not written as a clock. Young-earth Christians read Genesis 5 and 11 as complete and so shorten the early dates. The early dates themselves rest on king lists, layers in the ground and radiocarbon, and are more secure after about 2000 BC.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "hammurabi": {"id": "hammurabi", "label": "The laws of Hammurabi and the Law of Moses", "citation": "Diorite stele of Hammurabi of Babylon (about 1750 BC), found at Susa in 1901–02 by Jacques de Morgan’s expedition and published by Jean-Vincent Scheil (1902); Louvre, Sb 8. Martha T. Roth, Law Collections from Mesopotamia and Asia Minor (2nd ed., Scholars Press, 1997).", "trail": "The stele → Scheil 1902 → Roth 1997 → John H. Walton, Ancient Near Eastern Thought and the Old Testament (2nd ed., Baker, 2018).", "note": "Both collections deal with goring oxen, theft and injury, and both have “eye for eye” (Hammurabi laws 196–200; Exodus 21:23–25). The differences matter. Hammurabi’s penalties depend on class: a commoner’s eye is paid for in silver, a slave’s at half its price. Exodus protects a slave’s body and life (21:20, 26–27), and its laws come as God’s covenant with the whole people, not a king’s decree.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "hazor-ai": {"id": "hazor-ai", "label": "Hazor and Ai · burned cities in Joshua", "citation": "Yigael Yadin, Hazor: The Rediscovery of a Great Citadel of the Bible (Random House, 1975); Amnon Ben-Tor, “The Fall of Canaanite Hazor: The ‘Who’ and ‘When’ Questions,” in S. Gitin et al. (eds.), Mediterranean Peoples in Transition (Israel Exploration Society, 1998); Bryant G. Wood, “The Search for Joshua’s Ai,” in R. Hess, G. Klingbeil and P. Ray (eds.), Critical Issues in Early Israelite History (Eisenbrauns, 2008).", "trail": "Hazor excavations (Yadin 1955–58, 1968; Ben-Tor from 1990) → the essays above.", "note": "At Hazor a great fire ended the Canaanite city, with smashed statues of gods and kings. Ben-Tor holds that Israel burned it in the 13th century; early-date scholars point to an earlier destruction (Joshua 11:10–13). The usual site for Ai, et-Tell, was empty in Joshua’s day, so Wood and the Associates for Biblical Research excavated Khirbet el-Maqatir as the better candidate.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "herod-the-great": {"id": "herod-the-great", "label": "Herod the Great · Josephus and the stones", "citation": "Josephus, Antiquities 14–17 and Jewish War 1; Macrobius, Saturnalia 2.4.11 (Augustus’ joke that it was better to be Herod’s pig than his son). Ehud Netzer, The Architecture of Herod, the Great Builder (Mohr Siebeck, 2006).", "trail": "Josephus → Netzer’s excavations at Herodium, Masada, Jericho and Caesarea; Netzer found Herod’s tomb at Herodium in 2007.", "note": "Josephus records the executions of Herod’s wife Mariamne and his sons Alexander, Aristobulus and Antipater. No other source mentions the killing of Bethlehem’s infants (Matthew 2:16); a village of Bethlehem’s size might have lost a handful of boys, a small event by Herod’s standards.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "hill-villages": {"id": "hill-villages", "label": "The hill-country villages · Iron Age I", "citation": "Israel Finkelstein, The Archaeology of the Israelite Settlement (Israel Exploration Society, 1988); Avraham Faust, Israel’s Ethnogenesis (Equinox, 2006).", "trail": "Surface surveys of the central hills (1970s–80s) → Finkelstein 1988 → Faust 2006.", "note": "Surveys found about 250 new villages in the central hills in the 12th–11th centuries BC: four-room houses, plastered cisterns, terraced fields and almost no pig bones. Most scholars treat them as early Israel. How Israel came to be there is argued: conquest, gradual settlement, or a movement from within Canaan. Joshua and Judges themselves describe a quick campaign followed by a long, incomplete settlement.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "holy-sepulchre": {"id": "holy-sepulchre", "label": "The Church of the Holy Sepulchre · quarry, tombs and gardens", "citation": "Eusebius, Life of Constantine 3.25–40 (Hadrian’s temple removed; the tomb uncovered); Dan Bahat, “Does the Holy Sepulchre Church Mark the Burial of Jesus?” Biblical Archaeology Review 12:3 (1986); excavations under the church floor by Francesca Romana Stasolla (Sapienza University of Rome), 2022–.", "trail": "Eusebius → Virgilio Corbo’s excavations (1960s–70s) → Bahat 1986 → Stasolla.", "note": "Kathleen Kenyon’s work showed the site was outside the wall in AD 30. Rock-cut tombs of the period survive inside the church. Stasolla’s team reported pollen and remains of olive and vine from the Roman period, which fits John 19:41. The Garden Tomb, a popular alternative, is an older tomb of the Iron Age.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "isaiah-cyrus": {"id": "isaiah-cyrus", "label": "Isaiah names Cyrus · two readings", "citation": "Isaiah 44:28–45:1. One-author view: Oswald T. Allis, The Unity of Isaiah (Presbyterian & Reformed, 1950); John N. Oswalt, The Book of Isaiah, Chapters 40–66 (Eerdmans, 1998). Majority critical view: Joseph Blenkinsopp, Isaiah 40–55 (Anchor Bible, 2002). Josephus, Antiquities 11.5–6.", "trail": "Josephus → modern commentaries.", "note": "Those who hold one Isaiah of the 8th century read the naming of Cyrus as prediction; Josephus says Cyrus himself read it. Most critical scholars assign chapters 40–55 to a prophet writing in the exile about 540 BC. The Great Isaiah Scroll copies all 66 chapters as one book, with no break at chapter 40.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "jehoiachin-rations": {"id": "jehoiachin-rations", "label": "Jehoiachin’s rations · the king in Babylon", "citation": "Clay tablets from the Southern Palace of Babylon, excavated by Robert Koldewey (1899–1917); Vorderasiatisches Museum, Berlin. Ernst F. Weidner, “Jojachin, König von Juda, in babylonischen Keilschrifttexten,” in Mélanges syriens offerts à M. René Dussaud, vol. 2 (Paris, 1939).", "trail": "The tablets → Weidner 1939 → William F. Albright’s English discussion (Biblical Archaeologist, 1942).", "note": "Dated 592 BC, they list oil for “Ya’ukin, king of the land of Yahudu” and his five sons, among workers and captives from Tyre, Egypt, Ionia and elsewhere. 2 Kings 25:27–30 says he was later released and fed at the king’s table.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "jericho-dates": {"id": "jericho-dates", "label": "Jericho · the date of the fallen wall", "citation": "John Garstang (1930–36); Kathleen Kenyon, Digging Up Jericho (London, 1957); Bryant G. Wood, “Did the Israelites Conquer Jericho? A New Look at the Archaeological Evidence,” Biblical Archaeology Review 16:2 (1990); Hendrik J. Bruins and Johannes van der Plicht, “Tell es-Sultan (Jericho): Radiocarbon Results of Short-Lived Cereal and Multiyear Charcoal Samples from the End of the Middle Bronze Age,” Radiocarbon 37:2 (1995): 213–220.", "trail": "Ernst Sellin and Carl Watzinger (1907–09) → Garstang → Kenyon → Wood → Bruins and van der Plicht; the Italian-Palestinian excavations since 1997.", "note": "Garstang dated the burned city to about 1400 BC; Kenyon to about 1550, by the absence of imported Cypriot pottery. Wood re-dated the local pottery to about 1400. The radiocarbon dates on the burned grain came out near 1550 BC, supporting Kenyon. The evidence fits Joshua 6 in kind; the date is the open question.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "kurkh-monolith": {"id": "kurkh-monolith", "label": "The Kurkh Monolith · Ahab at Qarqar, 853 BC", "citation": "Monolith of Shalmaneser III from Kurkh, Turkey, found by J. E. Taylor in 1861; British Museum. Edited in A. K. Grayson, Assyrian Rulers of the Early First Millennium BC II (858–745 BC), Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (Toronto, 1996).", "trail": "The stone → Grayson 1996 → Kitchen, On the Reliability of the Old Testament (2003), ch. 2.", "note": "Shalmaneser lists “Ahab the Israelite” with 2,000 chariots and 10,000 soldiers. Some think the scribe miscopied the chariots (perhaps 200); either way Ahab’s force ranks among the largest. The Bible does not mention Qarqar; Assyria claimed a victory, but it did not advance for years.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "lachish-letters": {"id": "lachish-letters", "label": "The Lachish letters · “we cannot see Azekah”", "citation": "Ink-written potsherds (ostraca) from the gate of Lachish, found by J. L. Starkey in 1935 (more in 1938). Harry Torczyner, Lachish I: The Lachish Letters (Oxford, 1938). The letters are divided between the British Museum and the Israel Museum.", "trail": "The ostraca → Torczyner 1938 → Dennis Pardee in The Context of Scripture, vol. 3 (2002).", "note": "Letter 4 says the writer is watching for the signals of Lachish, “for we cannot see Azekah.” Some read this as meaning Azekah had already fallen (Jeremiah 34:7); others think the outpost simply could not see it from where it stood. Either way the letters come from the last weeks before Babylon’s conquest.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "laodicea-water": {"id": "laodicea-water", "label": "Laodicea’s water · hot, cold and lukewarm", "citation": "Revelation 3:15–16; M. J. S. Rudwick and E. M. B. Green, “The Laodicean Lukewarmness,” Expository Times 69 (1958): 176–178; Colin J. Hemer, The Letters to the Seven Churches of Asia in Their Local Setting (Sheffield, 1986).", "trail": "Rudwick (a geologist) and Green → Hemer 1986; Craig R. Koester, “The Message to Laodicea and the Problem of Its Local Context,” New Testament Studies 49 (2003): 407–424.", "note": "The reading in this book (hot is useful for healing, cold for drinking, lukewarm useless) is Rudwick and Green’s. Koester argues the image is more general: lukewarm drink makes anyone spit. Both agree the rebuke is about uselessness, not about keen versus hostile.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "luke-accuracy": {"id": "luke-accuracy", "label": "Luke as a historian", "citation": "W. M. Ramsay, St. Paul the Traveller and the Roman Citizen (London, 1895); Colin J. Hemer, The Book of Acts in the Setting of Hellenistic History (Mohr Siebeck, 1989); James Smith, The Voyage and Shipwreck of St. Paul (London, 1848).", "trail": "Ramsay’s travels in Asia Minor → Hemer’s catalogue of details in Acts 13–28 → Smith, a yachtsman, on Acts 27.", "note": "Ramsay began doubting Acts and came to regard Luke as a historian of the first rank. Smith checked Acts 27 against the winds, soundings and coast of Malta. Accurate setting does not by itself prove the miracles, but it shows a writer close to the events and careful with them.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "mari-archives": {"id": "mari-archives", "label": "The Mari archives · herders on the edge of the towns", "citation": "About 20,000 cuneiform tablets from the palace of Mari (Tell Hariri, Syria), 18th century BC, excavated by André Parrot from 1933 and published in the series Archives royales de Mari (1950– ).", "trail": "Palace archive → Archives royales de Mari → Daniel E. Fleming, Democracy’s Ancient Ancestors: Mari and Early Collective Governance (Cambridge, 2004) → K. A. Kitchen, On the Reliability of the Old Testament (Eerdmans, 2003), ch. 7.", "note": "The letters describe tribes such as the Binu Yamina (“sons of the south”) who moved flocks between pasture and towns and made covenants with settled kings, sealed by sacrifice. They do not mention Abraham. They show that the life Genesis describes belongs to the early second millennium BC.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "megiddo-mosaic": {"id": "megiddo-mosaic", "label": "The Megiddo prayer hall · “to God Jesus Christ”", "citation": "Yotam Tepper and Leah Di Segni, A Christian Prayer Hall of the Third Century CE at Kefar ‘Othnay (Legio): Excavations at the Megiddo Prison 2005 (Israel Antiquities Authority, 2006).", "trail": "The 2005 excavation → Tepper and Di Segni 2006 → Edward Adams, The Earliest Christian Meeting Places (T&T Clark, 2013).", "note": "The excavators dated the floor to about AD 230; some prefer the later 3rd century. It is before Constantine either way. The phrase “to God Jesus Christ” stands in a soldier’s building, in a province where Christianity was illegal.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "merneptah-stele": {"id": "merneptah-stele", "label": "The Merneptah Stele · “Israel” in Canaan, about 1208 BC", "citation": "Victory stele of Merneptah, granite, from his mortuary temple at Thebes; Egyptian Museum, Cairo, JE 31408. Found by W. M. Flinders Petrie in 1896; Six Temples at Thebes (London, 1897). English translation by James K. Hoffmeier in W. W. Hallo (ed.), The Context of Scripture, vol. 2 (Brill, 2000), no. 2.6.", "trail": "The stone → Petrie 1897 (Wilhelm Spiegelberg read the name) → Hoffmeier in The Context of Scripture.", "note": "Ashkelon, Gezer and Yanoam carry the sign for a foreign city-state; Israel carries the sign for a people. Scholars agree it names Israel; they debate what it implies, from a group recently settled in the hills to a people long in the land. A pedestal fragment in Berlin (ÄM 21687) may name Israel two centuries earlier; Manfred Görg proposed this in 2001, and the reading is still debated.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "nabonidus-belshazzar": {"id": "nabonidus-belshazzar", "label": "Nabonidus and Belshazzar · the second ruler", "citation": "Nabonidus Cylinders from Ur, found by J. E. Taylor in 1854 (one in the British Museum); the Nabonidus Chronicle (Chronicle 7, British Museum 35382); the Verse Account of Nabonidus (British Museum 38299). Raymond P. Dougherty, Nabonidus and Belshazzar (Yale, 1929).", "trail": "The cylinders and chronicle → Dougherty 1929 → Alan Millard, “Daniel and Belshazzar in History,” Biblical Archaeology Review 11:3 (1985).", "note": "The cylinders pray for “Belshazzar, my eldest son.” The chronicle says that for years the king stayed at Tema in Arabia while the crown prince was in Babylon; the Verse Account says he “entrusted the kingship” to him. Daniel 5:29 has Belshazzar make Daniel “third ruler.” Daniel calls Nebuchadnezzar his “father,” a common way of naming a royal predecessor.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-7-nabonidus-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, "nazareth": {"id": "nazareth", "label": "Nazareth in the first century", "citation": "Yardenna Alexandre (Israel Antiquities Authority), excavation of a first-century house, 2009; Ken Dark, Roman-Period and Byzantine Nazareth and Its Hinterland (Routledge, 2020). Michael Avi-Yonah, “A List of Priestly Courses from Caesarea,” Israel Exploration Journal 12 (1962): 137–139.", "trail": "Excavations under and near the Church of the Annunciation and the Sisters of Nazareth convent → Dark 2020.", "note": "The Caesarea inscription, of the 3rd–4th century, names Nazareth as the home of a priestly course after AD 70. Claims that Nazareth did not exist in Jesus’ day (René Salm, The Myth of Nazareth, 2008) have not persuaded archaeologists. Dark has argued that a first-century house under the convent may be the one Byzantine Christians honored as Jesus’ home; that remains a proposal.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "nero-tacitus": {"id": "nero-tacitus", "label": "Nero’s persecution · Tacitus and Suetonius", "citation": "Tacitus, Annals 15.38–44 (the fire of AD 64; Christus executed by Pontius Pilate under Tiberius); Suetonius, Nero 16.2.", "trail": "Tacitus (writing about AD 116) → Ronald Mellor, Tacitus (Routledge, 1993).", "note": "Tacitus says four of Rome’s fourteen districts were untouched, three leveled and seven badly damaged. He calls the Christians hated for their “abominations” and their faith a “deadly superstition,” and still reports the public’s pity. His statement on Christ’s execution under Pilate is accepted as genuine by nearly all historians.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Tacitus/Annals/15B*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, "new-creation": {"id": "new-creation", "label": "New creation · renewal, not escape", "citation": "Isaiah 65:17–25; Romans 8:19–23; 2 Peter 3:10–13; Revelation 21:1–5. N. T. Wright, Surprised by Hope (HarperOne, 2008); J. Richard Middleton, A New Heaven and a New Earth (Baker, 2014).", "trail": "The texts → Wright 2008 → Middleton 2014.", "note": "Christians agree that Christ will return, raise the dead and judge, and that God will dwell with his people. They differ on whether the present world is renewed or replaced. A textual point bears on it: in 2 Peter 3:10 the oldest manuscripts (Sinaiticus, Vaticanus) read that the earth “will be found” or “laid bare,” where later ones read “burned up.”", "url": "", "consulted": "Compiled from the published record, November 2026."}, "pentecost": {"id": "pentecost", "label": "Pentecost in Jerusalem", "citation": "Acts 2:1–11; Josephus, Antiquities 17.254 and Jewish War 2.42–44 (crowds at Pentecost in 4 BC); Jubilees 6:17–21; Craig S. Keener, Acts: An Exegetical Commentary, vol. 1 (Baker, 2012).", "trail": "Josephus and Jubilees → Keener 2012.", "note": "Pentecost, the Feast of Weeks, was one of three pilgrim feasts, and Josephus describes great crowds at it. Jubilees (2nd century BC) already ties the feast to covenant renewal; the rabbinic link with the giving of the Law at Sinai is recorded later. Luke’s list of nations follows the Jewish communities of his day, from Parthia to Rome.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "peter-paul-rome": {"id": "peter-paul-rome", "label": "Peter and Paul in Rome", "citation": "1 Clement 5 (about AD 96); Ignatius, Romans 4; Eusebius, Church History 2.25.5–8, quoting Gaius of Rome and Dionysius of Corinth; Tertullian, Prescription against Heretics 36.", "trail": "1 Clement → Eusebius → Markus Bockmuehl, Simon Peter in Scripture and Memory (Baker, 2012).", "note": "1 Clement, written from Rome within about thirty years, recalls both apostles’ witness and suffering. The manner of death (Peter crucified, Paul beheaded) comes from later 2nd- and 3rd-century writers, consistent with John 21:18–19.", "url": "https://www.newadvent.org/fathers/1010.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, "pilate-stone": {"id": "pilate-stone", "label": "The Pilate Stone · Caesarea, 1961", "citation": "Limestone block from the theater at Caesarea, found by the Italian expedition under Antonio Frova in 1961; Israel Museum. Géza Alföldy, “Pontius Pilatus und das Tiberieum von Caesarea Maritima,” Scripta Classica Israelica 18 (1999): 85–108.", "trail": "The stone → Frova’s first publication (1961) → Alföldy 1999.", "note": "The text names a Tiberieum, a building honoring Tiberius, and Pilate as praefectus Iudaeae. Alföldy read the building as a lighthouse for the harbor; others suggest a temple. In 2018 a copper ring from Herodium inscribed “of Pilatus” was published; it may belong to the governor or to a member of his staff.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "pliny-trajan": {"id": "pliny-trajan", "label": "Pliny’s letter to Trajan, about AD 112", "citation": "Pliny the Younger, Letters 10.96 and Trajan’s reply, 10.97.", "trail": "Pliny’s collected letters → A. N. Sherwin-White, The Letters of Pliny: A Historical and Social Commentary (Oxford, 1966).", "note": "Pliny writes that Christians sang “a hymn to Christ as to a god” (carmen Christo quasi deo) and calls the faith a depraved and excessive superstition. The two women were ministrae, the Latin equivalent of deaconesses. Trajan replies that Christians should not be hunted out or accused anonymously.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "protevangelium": {"id": "protevangelium", "label": "The first promise · Genesis 3:15", "citation": "Irenaeus, Against Heresies 5.21.1; R. A. Martin, “The Earliest Messianic Interpretation of Genesis 3:15,” Journal of Biblical Literature 84 (1965): 425–427.", "trail": "The Septuagint (3rd century BC) → Irenaeus (about AD 180) → Martin 1965.", "note": "The Greek translators used a masculine “he” for the woman’s offspring, a neuter noun in Greek; Martin took this as an early sign of reading the verse of one person. Irenaeus reads it of Christ. Many modern scholars read it of the long struggle between humanity and evil. The two readings can stand together, as Galatians 3:16 and Romans 16:20 suggest.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "qeiyafa-fortress": {"id": "qeiyafa-fortress", "label": "Khirbet Qeiyafa · a fortress in David’s day", "citation": "Yosef Garfinkel and Saar Ganor, Khirbet Qeiyafa, vol. 1: Excavation Report 2007–2008 (Israel Exploration Society, 2009); Yosef Garfinkel, Igor Kreimerman and Peter Zilberg, Debating Khirbet Qeiyafa: A Fortified City in Judah from the Time of King David (Israel Exploration Society, 2016).", "trail": "Excavation 2007–2013 → radiocarbon dates on olive pits → the reports above.", "note": "The excavators read a Judahite town of about 1000 BC; others propose a Saulide, Canaanite or Philistine-period site. Shaaraim (“two gates”, 1 Samuel 17:52) is their identification, debated by Nadav Na’aman and others. The ink ostracon found there in 2008 is early Hebrew or Canaanite writing; its translation is uncertain.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "resurrection-creed": {"id": "resurrection-creed", "label": "The early creed of 1 Corinthians 15", "citation": "1 Corinthians 15:3–8; Galatians 1:18–19. Gary R. Habermas and Michael R. Licona, The Case for the Resurrection of Jesus (Kregel, 2004); N. T. Wright, The Resurrection of the Son of God (Fortress, 2003); James D. G. Dunn, Jesus Remembered (Eerdmans, 2003).", "trail": "Paul’s letter (about AD 55) → his visit to Peter and James about three years after his conversion → Habermas, Wright and Dunn.", "note": "Paul uses the terms for receiving and handing on tradition. Most scholars date the formula to within a few years of the crucifixion; Dunn says it was formulated within months. The list includes Peter, James and more than five hundred, most still alive, inviting checking.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "roman-world": {"id": "roman-world", "label": "The Roman world · peace, roads and Greek", "citation": "Augustus, Res Gestae Divi Augusti 13 (the gates of Janus closed: peace on land and sea); Galatians 4:4; Acts 15:21. Everett Ferguson, Backgrounds of Early Christianity (3rd ed., Eerdmans, 2003).", "trail": "Augustus’ own account of his reign → Ferguson 2003.", "note": "The figure of 50,000 miles counts the main paved roads; with lesser roads the network was far larger. Josephus, Philo and inscriptions show Jewish communities and synagogues across the empire, with non-Jewish “God-fearers” attending (Acts 13:16, 26).", "url": "", "consulted": "Compiled from the published record, November 2026."}, "samaria-ivories": {"id": "samaria-ivories", "label": "Samaria · the ivory houses", "citation": "Harvard excavations led by George Reisner (1908–10) and the Joint Expedition under J. W. Crowfoot (1931–35); J. W. and G. M. Crowfoot, Early Ivories from Samaria (London, 1938).", "trail": "Excavation reports → Crowfoot 1938.", "note": "More than five hundred fragments of carved ivory, once set into furniture and wall panels, came from the royal quarter. Amos 3:15 and 6:4 condemn the “houses of ivory” and “beds of ivory”; 1 Kings 22:39 mentions Ahab’s ivory house. The Samaria ostraca, records of wine and oil, come from the same palace.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "sargon-samaria": {"id": "sargon-samaria", "label": "Sargon II and the fall of Samaria, 722–720 BC", "citation": "Sargon II’s annals at Khorsabad and the Nimrud Prism: 27,290 people deported (another text has 27,280). Babylonian Chronicle 1 says Shalmaneser V “ravaged Samaria.” K. Lawson Younger Jr., “The Deportations of the Israelites,” Journal of Biblical Literature 117 (1998): 201–227.", "trail": "Paul-Émile Botta found Sargon’s palace at Khorsabad in 1843 → the annals → Younger 1998.", "note": "2 Kings 17 credits the siege to Shalmaneser V and the capture to “the king of Assyria.” Sargon claimed the deportations in his own inscriptions. Most historians conclude that Shalmaneser took the city in 722 and Sargon completed the deportations and resettlement by 720.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "sennacherib-prism": {"id": "sennacherib-prism", "label": "Sennacherib’s prisms · Hezekiah “like a bird in a cage”", "citation": "Taylor Prism, British Museum; Oriental Institute Prism, Chicago; Jerusalem Prism, Israel Museum. Daniel David Luckenbill, The Annals of Sennacherib (Oriental Institute Publications 2, Chicago, 1924); A. Kirk Grayson and Jamie Novotny, Royal Inscriptions of the Neo-Assyrian Period 3/1 (2012).", "trail": "Prisms from Nineveh → Luckenbill 1924 → Grayson and Novotny 2012; on the murder, Simo Parpola, “The Murderer of Sennacherib,” in Death in Mesopotamia (1980); Herodotus, Histories 2.141.", "note": "Sennacherib claims 46 towns and 30 talents of gold, the same figure as 2 Kings 18:14 (the silver differs, 800 talents to 300). He never claims Jerusalem. Herodotus heard in Egypt that mice gnawed the Assyrians’ bowstrings in one night; 2 Kings 19:35 says the angel of the LORD struck the camp. Babylonian Chronicle 1 and Esarhaddon’s own inscription confirm his murder by a son (2 Kings 19:37).", "url": "", "consulted": "Compiled from the published record, November 2026."}, "slave-price": {"id": "slave-price", "label": "Twenty shekels · the price of a slave over time", "citation": "K. A. Kitchen, “The Patriarchal Age: Myth or History?” Biblical Archaeology Review 21:2 (1995); On the Reliability of the Old Testament (Eerdmans, 2003), ch. 7. Prices from the laws of Hammurabi and from Old Babylonian, Mari, Nuzi, Ugarit, Assyrian and Persian contracts.", "trail": "Contracts and law codes → Kitchen’s table of prices across fifteen centuries.", "note": "Kitchen’s table: about 20 shekels in the 18th–17th centuries BC (Genesis 37:28); about 30 in the 14th–13th (compare Exodus 21:32); 50–60 in Assyria in the 8th (compare 2 Kings 15:20); 90–120 under Persia. Critics answer that prices varied with age, skill and place. The trend is still the point: a writer guessing in a later century would likely have used the price of his own day.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "solomon-gates": {"id": "solomon-gates", "label": "Solomon’s gates · Hazor, Megiddo and Gezer", "citation": "Yigael Yadin, “Solomon’s City Wall and Gate at Gezer,” Israel Exploration Journal 8 (1958): 80–86; Israel Finkelstein, “The Archaeology of the United Monarchy: An Alternative View,” Levant 28 (1996): 177–187; William G. Dever, What Did the Biblical Writers Know and When Did They Know It? (Eerdmans, 2001).", "trail": "1 Kings 9:15 → Yadin read the three six-chambered gates as one royal plan → Finkelstein’s “low chronology” moved them later → Dever and Amihai Mazar defend a 10th-century date for Gezer.", "note": "The argument is about decades of pottery and radiocarbon dating. It decides whether the gates belong to Solomon or to the kings of Israel a few generations later. Students should know both sides and that the matter is still under study.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "tel-dan-stele": {"id": "tel-dan-stele", "label": "The Tel Dan Stele · “House of David”, about 840 BC", "citation": "Avraham Biran and Joseph Naveh, “An Aramaic Stele Fragment from Tel Dan,” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment,” IEJ 45 (1995): 1–18. Israel Museum, Jerusalem.", "trail": "Found by Gila Cook of Biran’s team, July 1993; fragments B1 and B2 in 1994 → Biran and Naveh → George Athas, The Tel Dan Inscription (Sheffield, 2003).", "note": "The phrase bytdwd is read “House of David” by nearly all specialists; a few early alternatives (a place name, “house of the kettle”) have not held. The speaker is most likely Hazael of Damascus, who claims the killings 2 Kings 9 credits to Jehu; perhaps Jehu acted in league with Hazael, or the king took credit. How the fragments join is still discussed.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "treaty-covenant": {"id": "treaty-covenant", "label": "Covenant and treaty · the shape of Sinai", "citation": "George E. Mendenhall, Law and Covenant in Israel and the Ancient Near East (Pittsburgh, 1955); Meredith G. Kline, Treaty of the Great King (Eerdmans, 1963); K. A. Kitchen and Paul J. N. Lawrence, Treaty, Law and Covenant in the Ancient Near East, 3 vols. (Harrassowitz, 2012).", "trail": "Hittite treaty tablets from Hattusa (Boğazköy) → Mendenhall 1955 → Kline 1963 → Kitchen and Lawrence 2012.", "note": "Hittite treaties of the 14th–13th centuries BC run: preamble, history, stipulations, deposit and public reading, witnesses, blessings and curses. Exodus 20–24 and Deuteronomy follow that order. Kitchen argues the shape fits the late second millennium better than the Assyrian treaties of the 7th century; scholars who date Deuteronomy late compare it with Esarhaddon’s succession treaties instead.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "ur-woolley": {"id": "ur-woolley", "label": "Ur of the Chaldeans", "citation": "Leonard Woolley, excavations at Tell el-Muqayyar, Iraq, 1922–1934; Ur of the Chaldees (London, 1929). Finds from the Royal Cemetery (about 2600 BC) are in the British Museum and the Penn Museum.", "trail": "Excavation reports → Woolley 1929 → Kitchen, On the Reliability of the Old Testament, ch. 7.", "note": "Genesis 11:31 uses “Chaldeans,” a people known in the region from about 1000 BC, so the name was probably updated for later readers, as we say “Iraq” for ancient Mesopotamia. Most identify Abraham’s Ur with Woolley’s city in the south; a minority, pointing to Haran, look for a northern Ur near Urfa.", "url": "", "consulted": "Compiled from the published record, November 2026."}, "yehohanan": {"id": "yehohanan", "label": "Yehohanan · the crucified man from Giv‘at ha-Mivtar", "citation": "Vassilios Tzaferis, “Jewish Tombs at and near Giv‘at ha-Mivtar, Jerusalem,” Israel Exploration Journal 20 (1970): 18–32; Joseph Zias and Eliezer Sekeles, “The Crucified Man from Giv‘at ha-Mivtar: A Reappraisal,” IEJ 35 (1985): 22–27. Israel Museum.", "trail": "The 1968 tomb → Tzaferis 1970 → Zias and Sekeles 1985.", "note": "The nail is about 11.5 cm long, bent at the tip, with a small wooden plate under its head. The 1985 reappraisal found no clear sign of nails in the arms, which may have been tied. A second heel with a nail was reported from Gavello, Italy, in 2018. Yehohanan was buried in a family tomb, as the Gospels say of Jesus.", "url": "", "consulted": "Compiled from the published record, November 2026."}}};
